function miniScreen(type){return `<div class="mini-screen"><div class="mini-sidebar"><b></b><i></i><i></i><i></i></div><div class="mini-main"><div class="mini-header"></div>${type==='knowledge'?`<div class="mini-docs">${[1,2,3].map(()=>'<div class="mini-doc"><b></b><i></i><i></i><i></i></div>').join('')}</div>`:`<div class="mini-metrics"><b>—</b><b>—</b><b>—</b></div>${[1,2,3].map(()=>'<div class="mini-row"><i></i><em></em><b></b></div>').join('')}`}</div></div>`;}
function home(){
 const cards=data.products.map((p,i)=>({id:p.id,title:p.title,tone:['','green','purple','sand'][i%4],icon:p.modules.length?'layers':'grid',text:p.description||'A source-registered product composition.',count:p.modules.length}));
 return head('Your products, one foundation.','Explore the reusable shells and assemble a different application from the same maintained modules.',btn(`${icon('plus',14)} Compose a product`,'go:composer','primary'))+`
 <div class="hero"><div><div class="eyebrow">A PLATFORM FOR BUILDING PRODUCTS</div><h2>Write the business logic.<br>Reuse everything around it.</h2><p>Your source manifests drive the library. One resolver validates every product. The paired local Studio builds and starts the selected application.</p>${btn(`Explore the architecture ${icon('arrow',14)}`,'go:architecture')}</div><div class="hero-visual"><div class="foundation-tile"><div class="tile-icon">${icon('layers',23)}</div><h3>Shared foundation</h3><p>Shell · hosts · contracts<br>Scope · data · execution</p></div><svg class="branch-lines" viewBox="0 0 27 144" fill="none" stroke="currentColor"><path d="M0 72h12V22h15M12 72h15M12 72v50h15"/></svg><div class="mini-products">${cards.slice(0,3).map(c=>`<div class="mini-product"><i>${icon(c.icon,15)}</i>${esc(c.title)}</div>`).join('')}</div></div></div>
 <div class="section-title"><h2>Registered product compositions <span class="small-muted"> / ${String(cards.length).padStart(2,'0')}</span></h2><p>Derived from products/*/product.json · not deployment status</p></div><div class="product-grid">${cards.map(c=>`<article class="product-card ${c.tone}"><div class="card-top">${miniScreen(c.id)}</div><div class="card-body"><div class="product-title"><h3>${esc(c.title)}</h3><span class="small-icon">${icon(c.icon,16)}</span></div><p>${esc(c.text)}</p><div class="card-meta"><span>${c.count} selected modules</span>${pill('Source definition')}</div>${btn(`Inspect product ${icon('arrow',13)}`,`product:${c.id}`)}</div></article>`).join('')}</div>
 ${state.drafts.length?`<div class="section-title"><h2>Your preview drafts</h2><p>Page-session only · not source files</p></div><div class="module-grid">${state.drafts.map((d,i)=>`<div class="module-card"><div class="module-icon">${icon('layers')}</div><h3>${esc(d.title)}</h3><p>${d.modules.length} modules · ${esc(d.layout)} navigation</p>${btn('Export product.json',`draft:${i}`)}</div>`).join('')}</div>`:''}
 <div class="overview-bottom"><section class="panel"><h3>Maintained packages, not copied applications.</h3><p>Products supply their own composition and domain behavior.</p><div class="stack-bars">${Object.values(packageMeta).map(p=>`<span>${esc(p.title)}</span>`).join('')}</div></section><section class="panel"><h3>From composition to a real result.</h3><p>Open the authenticated local Studio to save, build and run. Sample screens remain clearly separate.</p><div class="simple-flow"><span>Validate</span><i>→</i><span>Build snapshot</span><i>→</i><span>Open application</span></div></section></div>`;
}
function builderProduct(){return compose(state.builder.id,state.builder.title,state.builder.selected,state.builder.layout);}
